<script setup lang="ts">
/**
 * Plays one recording (`design/components/audio-player.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/audio-player.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import { Icon, agentMember, clockTime, pauseOtherPlayers, spokenDuration } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/audio-player.module.css'
import Button from '../controls/Button.vue'
import Slider from '../controls/Slider.vue'

export interface AudioPlayerMessages {
  /** The Button's name while the recording is not playing: "Play". */
  play: string
  /** The Button's name while it plays: "Pause". */
  pause: string
  /** The scrubber's name: "Playback position". */
  scrubber: string
  /** The scrubber's spoken value, from the elapsed and the total length. */
  position: (elapsed: string, total: string) => string
  /** Said in place of the scrubber when the file cannot be loaded. */
  failed: string
}

export interface AudioPlayerProps {
  /**
   * The recording's length in seconds, shown before the file gives its own. A file's finite
   * length replaces it. A file that gives none, as a recording a browser's `MediaRecorder`
   * wrote, keeps it.
   */
  duration?: number
  /**
   * Names the player, as a group: "Voice message from Ada".
   */
  label: string
  /**
   * The locale the clock and the spoken lengths are written in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: AudioPlayerMessages
  /**
   * The recording's URL. An empty string is the failed state: there is nothing to load.
   */
  src: string
}

defineOptions({ name: 'AudioPlayer', inheritAttrs: false })

const props = withDefaults(defineProps<AudioPlayerProps>(), {
  messages: () => ({
    play: 'Play',
    pause: 'Pause',
    scrubber: 'Playback position',
    position: (elapsed: string, total: string) => `${elapsed} of ${total}`,
    failed: 'The recording could not be loaded',
  }),
})
const emit = defineEmits<{ ended: []; play: [] }>()
const uid = useId()
const playing = ref(false)
const finished = ref(false)
const elapsed = ref(0)
const fileLength = ref(null as number | null)
const failed = ref(null as string | null)
const scrub = ref(null as number | null)
const audio = useTemplateRef<HTMLElement>('audio')
const root = useTemplateRef<HTMLElement>('root')
const known = computed(
  () =>
    fileLength.value ??
    (props.duration !== undefined && Number.isFinite(props.duration) && props.duration > 0
      ? props.duration
      : null),
)
const total = computed(() => (known.value === null ? 0 : Math.floor(known.value)))
const failing = computed(() => props.src === '' || failed.value === props.src)
const seekable = computed(() => !failing.value && total.value >= 1)
const position = computed(() =>
  finished.value ? total.value : Math.min(scrub.value ?? elapsed.value, total.value),
)
const status = computed(() =>
  failing.value ? 'failed' : playing.value ? 'playing' : finished.value ? 'ended' : undefined,
)
const failureId = computed(() => `${uid}-failure`)
const spoken = computed(
  () =>
    (second: number): string =>
      known.value === null
        ? spokenDuration(second, props.locale)
        : props.messages.position(
            spokenDuration(second, props.locale),
            spokenDuration(total.value, props.locale),
          ),
)
const learn = computed(() => (): void => {
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element == null) return
  const seconds = element.duration
  fileLength.value = Number.isFinite(seconds) && seconds > 0 ? seconds : null
})
const settle = computed(() => (): void => {
  playing.value = false
  finished.value = false
  elapsed.value = 0
  fileLength.value = null
  scrub.value = null
  if (failed.value !== props.src) failed.value = null
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element == null) return
  if (element.error !== null) failed.value = props.src
  else if (element.readyState >= 1) learn.value()
})
const toggle = computed(() => (): void => {
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element == null) return
  if (!element.paused) {
    element.pause()
    return
  }
  if (failing.value) {
    failed.value = null
    element.load()
  }
  element.play().catch(() => {})
})
const secondOf = computed(
  () =>
    (value: number | [number, number]): number =>
      typeof value === 'number' ? value : value[0],
)
const seek = computed(() => (second: number): void => {
  scrub.value = null
  elapsed.value = second
  finished.value = false
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element != null) element.currentTime = second
})
const started = computed(() => (): void => {
  playing.value = true
  finished.value = false
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element != null) pauseOtherPlayers(element)
  emit('play')
})
const stopped = computed(() => (): void => {
  playing.value = false
  finished.value = true
  emit('ended')
})
const ticked = computed(() => (): void => {
  const element = audio.value as HTMLAudioElement | null | undefined
  if (element != null) elapsed.value = Math.floor(element.currentTime)
})
const effect1 = () => {
  settle.value()
}
onMounted(effect1)
watch(() => props.src, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'AudioPlayer',
    element: () => root.value,
    state: () => ({
      playing: playing.value,
      failed: failing.value,
      position: position.value,
      duration: total.value,
    }),
    actions: {},
    withholds: () => root.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    role="group"
    :aria-label="label"
    :data-state="status"
    data-member="audio-player"
  >
    <!-- audio -->
    <audio
      v-if="src !== ''"
      ref="audio"
      preload="metadata"
      :src="src"
      @loadedmetadata="learn()"
      @durationchange="learn()"
      @timeupdate="ticked()"
      @play="started()"
      @pause="playing = false"
      @ended="stopped()"
      @error="((failed = src), (playing = false))"
    />
    <Button
      variant="soft"
      tone="accent"
      :iconOnly="true"
      :icon="playing ? 'pause' : 'run'"
      :label="playing ? messages.pause : messages.play"
      :disabled="src === ''"
      :aria-describedby="failing ? failureId : undefined"
      @click="toggle()"
    />
    <!-- failure -->
    <span v-if="failing" :class="styles.failure" :id="failureId" data-audio-player-part="failure">
      <span :class="styles.failureGlyph" aria-hidden="true">
        <Icon name="error" size="sm" />
      </span>
      <span>
        {{ messages.failed }}
      </span>
    </span>
    <template v-else>
      <!-- scrubber -->
      <span :class="styles.scrubber">
        <Slider
          :aria-label="messages.scrubber"
          :min="0"
          :max="seekable ? total : 1"
          :step="1"
          :value="seekable ? position : 0"
          :disabled="!seekable"
          :formatValue="spoken"
          @change="
            (value: number | [number, number]) => {
              scrub = secondOf(value)
            }
          "
          @commit="(value: number | [number, number]) => seek(scrub ?? secondOf(value))"
        />
      </span>
      <!-- time -->
      <span :class="styles.time" data-audio-player-part="time" aria-hidden="true">
        <span>
          {{ clockTime(position, locale) }}
        </span>
        <template v-if="known !== null">
          <span :class="styles.divider">
            {{ '/' }}
          </span>
          <span>
            {{ clockTime(total, locale) }}
          </span>
        </template>
      </span>
    </template>
  </div>
</template>
